&lt;/head&gt;
&lt;body&gt;
    &lt;h1&gt;Sales Representatives&lt;/h1&gt;
    &lt;form action=&quot;{{ url_for(&#x27;add_sales_rep&#x27;) }}&quot; method=&quot;POST&quot;&gt;
        &lt;input type=&quot;text&quot; name=&quot;name&quot; placeholder=&quot;Sales Rep Name&quot; required&gt;
        &lt;button type=&quot;submit&quot;&gt;Add Sales Rep&lt;/button&gt;
    &lt;/form&gt;
    &lt;ul&gt;
        {% for rep in sales_reps %}
        &lt;li&gt;&lt;a href=&quot;{{ url_for(&#x27;sales_rep&#x27;, id=rep.id) }}&quot;&gt;{{ rep.name }}&lt;/a&gt;&lt;/li&gt;
        {% endfor %}
    &lt;/ul&gt;
    &lt;a href=&quot;{{ url_for(&#x27;logout&#x27;) }}&quot;&gt;Logout&lt;/a&gt;
&lt;/body&gt;
&lt;/html&gt;
```

- **`templates/sales_rep.html`**

```html
&lt;!doctype html&gt;
&lt;html&gt;
&lt;head&gt;
    &lt;title&gt;{{ sales_rep.name }}&#x27;s Deals&lt;/title&gt;
&lt;/head&gt;
&lt;body&gt;
    &lt;h1&gt;{{ sales_rep.name }}&#x27;s Deals&lt;/h1&gt;
    &lt;form action=&quot;{{ url_for(&#x27;add_deal&#x27;, sales_rep_id=sales_rep.id) }}&quot; method=&quot;POST&quot;&gt;
        &lt;input type=&quot;text&quot; name=&quot;description&quot; placeholder=&quot;Deal Description&quot; required&gt;
        &lt;input type=&quot;number&quot; step=&quot;0.01&quot; name=&quot;value&quot; placeholder=&quot;Deal Value&quot; required&gt;
        &lt;button type=&quot;submit&quot;&gt;Add Deal&lt;/button&gt;
    &lt;/form&gt;
    &lt;h2&gt;Top 5 Deals&lt;/h2&gt;
    &lt;ul&gt;
        {% for deal in sales_rep.deals|sort(attribute=&#x27;value&#x27;, reverse=True)[:5] %}
        &lt;li&gt;{{ deal.description }} - ${{ deal.value }}&lt;/li&gt;
